const body = $input.first().json.body || {};
const query = $input.first().json.query || {};

const scriptId = body.script_id || query.script_id || '';
const variations = body.variations || query.variations || 'all';
// variations: 'all', 'hooks', 'lengths', 'angles'

if (!scriptId) {
  throw new Error('script_id is required');
}

return [{ json: { script_id: scriptId, variations } }];

const parseData = $('rep-parse').first().json;
const scriptRecord = $('rep-fetch-script').first().json;
const fields = scriptRecord.fields || {};

// Get learnings
let learnings = [];
try {
  const lr = $('rep-fetch-learnings').first().json;
  learnings = (lr.records || []).map(r => ({
    category: r.fields?.category || '',
    title: r.fields?.title || '',
    insight: r.fields?.insight || '',
    confidence: r.fields?.confidence || 0
  }));
} catch(e) {}

// Get brand voice
let brandVoice = '';
let brandName = '';
try {
  const brands = $('rep-fetch-brand').first().json;
  const projectIds = fields.project_id || [];
  const projectId = Array.isArray(projectIds) ? projectIds[0] : projectIds;

  // Try to match brand via project - for now just get all brands and use first match
  // In practice, the brand_voice field on the script's project would link to a brand
  if (brands.records && brands.records.length > 0) {
    for (const b of brands.records) {
      if (b.fields?.brand_voice) {
        brandVoice = b.fields.brand_voice;
        brandName = b.fields?.brand_name || b.fields?.name || '';
        break; // Use first brand with voice data
      }
    }
  }
} catch(e) {}

return [{ json: {
  script_id: scriptRecord.id,
  variations: parseData.variations,
  project_id: (fields.project_id || [])[0] || '',
  concept_id: (fields.concept_id || [])[0] || '',
  full_script: fields.full_script || '',
  hook: fields.hook || '',
  hook_1: fields.hook_1 || '',
  hook_2: fields.hook_2 || '',
  hook_3: fields.hook_3 || '',
  hook_reinforcement: fields.hook_reinforcement || '',
  problem: fields.problem || '',
  solution: fields.solution || '',
  proof: fields.proof || '',
  cta: fields.cta || '',
  visual_direction: fields.visual_direction || '',
  on_screen_text: fields.on_screen_text || '',
  creator_notes: fields.creator_notes || '',
  estimated_duration: fields.estimated_duration || '',
  concept_story: fields.concept_story || '',
  creative_table_json: fields.creative_table_json || '',
  script_number: fields.script_number || '',
  qa_score: fields.qa_score || 0,
  system_learnings: learnings,
  brand_voice: brandVoice,
  brand_name: brandName
}}];

const s = $input.first().json;

// Format system learnings for prompt injection
let learningsBlock = '';
if (s.system_learnings && s.system_learnings.length > 0) {
  learningsBlock = '\n\n== SYSTEM LEARNINGS (proven patterns from past campaigns) ==\n';
  for (const l of s.system_learnings) {
    learningsBlock += `- [${l.category}] ${l.title}: ${l.insight} (confidence: ${l.confidence}/10)\n`;
  }
  learningsBlock += '\nApply these learnings where relevant. Prioritize high-confidence insights.\n';
}

// Format brand voice DNA
let brandVoiceBlock = '';
if (s.brand_voice) {
  let voiceData = s.brand_voice;
  // If it's a JSON string, try to make it readable
  try {
    const parsed = JSON.parse(voiceData);
    voiceData = JSON.stringify(parsed, null, 2);
  } catch(e) {
    // Already a string, use as-is
  }
  brandVoiceBlock = `\n\n== BRAND VOICE DNA${s.brand_name ? ' (' + s.brand_name + ')' : ''} ==\n${voiceData}\n\nEvery variation MUST match this brand voice. The tone, vocabulary, and personality should feel consistent with the brand identity above.\n`;
}

const systemPrompt = `You are a senior UGC ad creative director. You take winning ad scripts and create variations that test different angles, hooks, lengths, and energy levels.

You know that the #1 driver of ad performance is the HOOK — the first 3 seconds. Different hooks attract different segments of the same audience. You also know that shorter ads often outperform longer ones on Meta/TikTok, and that the same product story can be told through completely different angles.

RULES:
- Every variation must be a COMPLETE, ready-to-film script. Not an outline.
- Each hook must use a genuinely DIFFERENT psychological trigger — not the same idea reworded.
- Keep the core product truth the same. Change the angle, not the facts.
- Write like a real person talks. No marketing jargon.
- Each script variation should specify: hook (first 3 sec), body, CTA, estimated duration, and creator energy note.

BANNED PHRASES (never use these — they are overused and destroy authenticity):
- "game-changer"
- "literally obsessed"
- "I can't believe"
- "you need this"
- "trust me"
- "not sponsored" (when it is)
- "best thing ever"
- "life-changing"

HOOK DIFFERENTIATION RULES:
- Curiosity hook: Must create an information gap. Use specificity (numbers, unexpected details).
- Controversy hook: Must challenge a common belief or industry norm. Should feel like a hot take, not clickbait.
- Story hook: Must start mid-action or mid-emotion. Never start with "So I was..." — drop us INTO the moment.${learningsBlock}${brandVoiceBlock}`;

const userPrompt = `Here's a winning ad script. Create variations.

== ORIGINAL SCRIPT ==
Hook: ${s.hook}
Hook variations: ${s.hook_1} / ${s.hook_2} / ${s.hook_3}
Hook reinforcement: ${s.hook_reinforcement}
Problem: ${s.problem}
Solution: ${s.solution}
Proof: ${s.proof}
CTA: ${s.cta}
Visual direction: ${s.visual_direction}
Creator notes: ${s.creator_notes}
Duration: ${s.estimated_duration}
Concept: ${s.concept_story}

Full script:
${s.full_script}

== CREATE THESE VARIATIONS ==

1. THREE NEW HOOKS (keep body + CTA same, just swap the opening 3 seconds):
   - Curiosity hook: Open with a question or mystery that makes them NEED to watch
   - Controversy hook: Open with a bold claim or hot take that stops the scroll
   - Story hook: Open with a personal "I" story that pulls them in emotionally

2. TWO LENGTH VARIANTS:
   - 15-second version: Hook + one key benefit + CTA. That's it. Ruthlessly short.
   - 45-second version: Full story arc. Hook + problem + solution + proof + CTA with room to breathe.

3. TWO ANGLE VARIANTS (same product, completely different approach):
   - "Friend recommending" angle: Casual, like texting a friend about something you found
   - "Skeptic converted" angle: Start doubting the product, show the moment you changed your mind

Return ONLY valid JSON (no markdown fences):
{
  "original_hook": "${s.hook.replace(/"/g, "'")}",
  "new_hooks": [
    {
      "type": "curiosity",
      "hook_text": "The actual words the creator says in first 3 seconds",
      "why_it_works": "One sentence on why this hook stops the scroll"
    },
    {
      "type": "controversy",
      "hook_text": "...",
      "why_it_works": "..."
    },
    {
      "type": "story",
      "hook_text": "...",
      "why_it_works": "..."
    }
  ],
  "length_variants": [
    {
      "duration": "15s",
      "full_script": "Complete 15-second script — every word the creator says",
      "visual_notes": "What's on screen",
      "energy": "Fast, punchy, confident"
    },
    {
      "duration": "45s",
      "full_script": "Complete 45-second script — every word",
      "visual_notes": "What's on screen",
      "energy": "Conversational, storytelling pace"
    }
  ],
  "angle_variants": [
    {
      "angle": "friend_recommending",
      "full_script": "Complete script — casual friend energy",
      "hook": "Opening line",
      "cta": "Closing line",
      "visual_notes": "Setting and vibe",
      "duration": "30s",
      "energy": "Casual, genuine, like a voice note to your bestie"
    },
    {
      "angle": "skeptic_converted",
      "full_script": "Complete script — starts skeptical, ends convinced",
      "hook": "Opening line",
      "cta": "Closing line",
      "visual_notes": "Setting and vibe",
      "duration": "30s",
      "energy": "Honest, relatable, the turning point is the climax"
    }
  ]
}`;

return [{ json: {
  ...s,
  requestBody: {
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    generationConfig: { temperature: 0.85, maxOutputTokens: 8192 }
  }
}}];

const geminiText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const original = $('rep-merge-context').first().json;

// Parse the generation output
let cleaned = geminiText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let variations = {};
try {
  variations = JSON.parse(cleaned);
} catch(e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { variations = JSON.parse(match[0]); } catch(e2) {
      let salvage = match[0].replace(/,\s*$/, '');
      let ob = (salvage.match(/\{/g)||[]).length;
      let cb = (salvage.match(/\}/g)||[]).length;
      let oB = (salvage.match(/\[/g)||[]).length;
      let cB = (salvage.match(/\]/g)||[]).length;
      for (let i=0;i<oB-cB;i++) salvage+=']';
      for (let i=0;i<ob-cb;i++) salvage+='}';
      try { variations = JSON.parse(salvage); } catch(e3) {
        variations = { error: 'parse failed', raw: geminiText.substring(0,2000) };
      }
    }
  }
}

// Build evaluation prompt
const hooks = variations.new_hooks || [];
const lengths = variations.length_variants || [];
const angles = variations.angle_variants || [];

let variationsSummary = 'VARIATIONS TO EVALUATE:\n\n';

for (let i = 0; i < hooks.length; i++) {
  variationsSummary += `--- Hook Variation ${i+1} (${hooks[i].type}) ---\n`;
  variationsSummary += `Hook: ${hooks[i].hook_text}\n`;
  variationsSummary += `Why: ${hooks[i].why_it_works}\n\n`;
}
for (let i = 0; i < lengths.length; i++) {
  variationsSummary += `--- Length Variation (${lengths[i].duration}) ---\n`;
  variationsSummary += `Script: ${lengths[i].full_script}\n`;
  variationsSummary += `Energy: ${lengths[i].energy}\n\n`;
}
for (let i = 0; i < angles.length; i++) {
  variationsSummary += `--- Angle Variation (${angles[i].angle}) ---\n`;
  variationsSummary += `Hook: ${angles[i].hook}\n`;
  variationsSummary += `Script: ${angles[i].full_script}\n`;
  variationsSummary += `Energy: ${angles[i].energy}\n\n`;
}

// Brand voice context for evaluation
let brandContext = '';
if (original.brand_voice) {
  brandContext = `\n\nBRAND VOICE DNA:\n${original.brand_voice}\n`;
}

const evalSystemPrompt = `You are a ruthless ad creative QA evaluator. You score UGC ad script variations on strict criteria. You do NOT give generous scores — a 7 means "good enough to test", an 8 means "strong", a 9 means "exceptional". Most scripts should score 6-8.`;

const evalUserPrompt = `Evaluate each of these 7 ad script variations against the original script.

ORIGINAL SCRIPT:
Hook: ${original.hook}
Full script: ${original.full_script}
Brand: ${original.brand_name || 'Unknown'}${brandContext}

${variationsSummary}

Score each variation on these 5 criteria (1-10 scale):
1. hook_strength: Does the hook stop the scroll in 3 seconds? Is it specific, not generic?
2. authenticity: Does it sound like a real person talking, not a marketer? Would you skip this ad?
3. brand_alignment: Does it match the brand voice DNA? (If no brand voice provided, score on general consistency)
4. differentiation: Is this genuinely different from the original and other variations? Or just a rewording?
5. production_feasibility: Can a solo creator actually film this with a phone? No unrealistic setups.

For each WEAK variation (average score < 7), explain specifically:
- What's wrong
- How to fix it
- What psychological trigger or angle would work better

Return ONLY valid JSON (no markdown fences):
{
  "evaluations": [
    {
      "variation_index": 0,
      "variation_type": "hook_curiosity",
      "scores": {
        "hook_strength": 8,
        "authenticity": 7,
        "brand_alignment": 8,
        "differentiation": 7,
        "production_feasibility": 9
      },
      "avg_score": 7.8,
      "is_weak": false,
      "weakness_feedback": ""
    }
  ],
  "overall_assessment": "One sentence summary of quality",
  "weak_count": 0
}`;

return [{ json: {
  generatedVariations: variations,
  originalContext: original,
  evalRequestBody: {
    systemInstruction: { parts: [{ text: evalSystemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: evalUserPrompt }] }],
    generationConfig: { temperature: 0.3, maxOutputTokens: 4096, thinkingConfig: { thinkingBudget: 0 } }
  }
}}];

const evalText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const upstream = $('rep-build-eval-prompt').first().json;
const generatedVariations = upstream.generatedVariations;
const originalContext = upstream.originalContext;

// Parse evaluation JSON
let cleaned = evalText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let evalResult = {};
try {
  evalResult = JSON.parse(cleaned);
} catch(e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { evalResult = JSON.parse(match[0]); } catch(e2) {
      let salvage = match[0].replace(/,\s*$/, '');
      let ob = (salvage.match(/\{/g)||[]).length;
      let cb = (salvage.match(/\}/g)||[]).length;
      let oB = (salvage.match(/\[/g)||[]).length;
      let cB = (salvage.match(/\]/g)||[]).length;
      for (let i=0;i<oB-cB;i++) salvage+=']';
      for (let i=0;i<ob-cb;i++) salvage+='}';
      try { evalResult = JSON.parse(salvage); } catch(e3) {
        // If eval parse fails entirely, pass everything through as-is
        evalResult = { evaluations: [], weak_count: 0 };
      }
    }
  }
}

const evaluations = evalResult.evaluations || [];
const weakCount = evalResult.weak_count || evaluations.filter(e => e.is_weak).length;

// Identify weak variations
const weakVariations = evaluations.filter(e => {
  if (e.is_weak) return true;
  if (e.avg_score && e.avg_score < 7) return true;
  if (e.scores) {
    const vals = Object.values(e.scores);
    const avg = vals.reduce((a,b) => a+b, 0) / vals.length;
    if (avg < 7) return true;
  }
  return false;
});

return [{ json: {
  needsRetry: weakVariations.length > 0,
  weakCount: weakVariations.length,
  evaluations: evaluations,
  weakVariations: weakVariations,
  overallAssessment: evalResult.overall_assessment || '',
  generatedVariations: generatedVariations,
  originalContext: originalContext
}}];

const data = $input.first().json;
const original = data.originalContext;
const variations = data.generatedVariations;
const weakVars = data.weakVariations || [];
const evaluations = data.evaluations || [];

// Build the list of what needs fixing
let weakFeedback = 'WEAK VARIATIONS THAT NEED REWRITING:\n\n';
for (const w of weakVars) {
  weakFeedback += `--- ${w.variation_type || 'Variation ' + w.variation_index} ---\n`;
  if (w.scores) {
    weakFeedback += `Scores: hook_strength=${w.scores.hook_strength}, authenticity=${w.scores.authenticity}, brand_alignment=${w.scores.brand_alignment}, differentiation=${w.scores.differentiation}, production_feasibility=${w.scores.production_feasibility}\n`;
  }
  weakFeedback += `Average: ${w.avg_score || 'N/A'}\n`;
  weakFeedback += `Feedback: ${w.weakness_feedback || 'Below threshold'}\n\n`;
}

// Identify which variations are strong (to keep)
const strongEvals = evaluations.filter(e => {
  if (e.is_weak) return false;
  if (e.avg_score && e.avg_score < 7) return false;
  if (e.scores) {
    const vals = Object.values(e.scores);
    const avg = vals.reduce((a,b) => a+b, 0) / vals.length;
    if (avg < 7) return false;
  }
  return true;
});

// Brand voice context
let brandContext = '';
if (original.brand_voice) {
  brandContext = `\nBRAND VOICE DNA:\n${original.brand_voice}\n`;
}

// System learnings context
let learningsBlock = '';
if (original.system_learnings && original.system_learnings.length > 0) {
  learningsBlock = '\nSYSTEM LEARNINGS:\n';
  for (const l of original.system_learnings) {
    learningsBlock += `- [${l.category}] ${l.title}: ${l.insight}\n`;
  }
}

const retrySystemPrompt = `You are a senior UGC ad creative director doing a revision pass. Some of the script variations you wrote scored below quality threshold. Rewrite ONLY the weak ones. Keep the strong ones exactly as they are.

BANNED PHRASES: "game-changer", "literally obsessed", "I can't believe", "you need this", "trust me", "not sponsored", "best thing ever", "life-changing".

Each hook must use a genuinely DIFFERENT psychological trigger. Write like a real person talks.${brandContext}${learningsBlock}`;

const retryUserPrompt = `ORIGINAL SCRIPT:
Hook: ${original.hook}
Full script: ${original.full_script}

CURRENT VARIATIONS (your first attempt):
${JSON.stringify(variations, null, 2)}

${weakFeedback}

Rewrite ONLY the weak variations listed above. Make them score 7+ on all criteria.

Return the COMPLETE set of all 7 variations — keep strong ones exactly as-is, replace weak ones with improved versions.

Return ONLY valid JSON (no markdown fences) in the exact same format:
{
  "original_hook": "${(original.hook || '').replace(/"/g, "'")}",
  "new_hooks": [
    { "type": "curiosity", "hook_text": "...", "why_it_works": "..." },
    { "type": "controversy", "hook_text": "...", "why_it_works": "..." },
    { "type": "story", "hook_text": "...", "why_it_works": "..." }
  ],
  "length_variants": [
    { "duration": "15s", "full_script": "...", "visual_notes": "...", "energy": "..." },
    { "duration": "45s", "full_script": "...", "visual_notes": "...", "energy": "..." }
  ],
  "angle_variants": [
    { "angle": "friend_recommending", "full_script": "...", "hook": "...", "cta": "...", "visual_notes": "...", "duration": "30s", "energy": "..." },
    { "angle": "skeptic_converted", "full_script": "...", "hook": "...", "cta": "...", "visual_notes": "...", "duration": "30s", "energy": "..." }
  ]
}`;

return [{ json: {
  originalContext: original,
  strongEvals: strongEvals,
  firstPassVariations: variations,
  retryRequestBody: {
    systemInstruction: { parts: [{ text: retrySystemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: retryUserPrompt }] }],
    generationConfig: { temperature: 0.75, maxOutputTokens: 8192 }
  }
}}];

const geminiText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const upstream = $('rep-build-retry-prompt').first().json;
const original = upstream.originalContext;
const firstPass = upstream.firstPassVariations;

// Parse retry output
let cleaned = geminiText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let retryVariations = {};
try {
  retryVariations = JSON.parse(cleaned);
} catch(e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { retryVariations = JSON.parse(match[0]); } catch(e2) {
      let salvage = match[0].replace(/,\s*$/, '');
      let ob = (salvage.match(/\{/g)||[]).length;
      let cb = (salvage.match(/\}/g)||[]).length;
      let oB = (salvage.match(/\[/g)||[]).length;
      let cB = (salvage.match(/\]/g)||[]).length;
      for (let i=0;i<oB-cB;i++) salvage+=']';
      for (let i=0;i<ob-cb;i++) salvage+='}';
      try { retryVariations = JSON.parse(salvage); } catch(e3) {
        // If retry parse fails, fall back to first pass
        retryVariations = firstPass;
      }
    }
  }
}

// The retry prompt asked for the COMPLETE set with improvements merged in,
// so retryVariations should have all 7. If parsing failed, fall back to firstPass.
const finalVariations = retryVariations.new_hooks ? retryVariations : firstPass;

return [{ json: {
  candidates: [{
    content: {
      parts: [{ text: JSON.stringify(finalVariations) }]
    }
  }]
}}];

const original = $('rep-merge-context').first().json;

// Accept input from either the direct path (no retry needed) or the retry path
const inputData = $input.first().json;

// Determine where the variations JSON comes from
let geminiText = '';
if (inputData.candidates) {
  // Coming from rep-merge-final (retry path) — already cleaned JSON in text
  geminiText = inputData.candidates?.[0]?.content?.parts?.[0]?.text || '';
} else if (inputData.generatedVariations) {
  // Coming from rep-parse-eval via rep-needs-retry false path
  geminiText = JSON.stringify(inputData.generatedVariations);
} else {
  // Fallback: try to parse as Gemini raw response
  geminiText = inputData.candidates?.[0]?.content?.parts?.[0]?.text || JSON.stringify(inputData);
}

// Parse JSON
let cleaned = geminiText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let variations = {};
try {
  variations = JSON.parse(cleaned);
} catch(e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { variations = JSON.parse(match[0]); } catch(e2) {
      let salvage = match[0].replace(/,\s*$/, '');
      let ob = (salvage.match(/\{/g)||[]).length;
      let cb = (salvage.match(/\}/g)||[]).length;
      let oB = (salvage.match(/\[/g)||[]).length;
      let cB = (salvage.match(/\]/g)||[]).length;
      for (let i=0;i<oB-cB;i++) salvage+=']';
      for (let i=0;i<ob-cb;i++) salvage+='}';
      try { variations = JSON.parse(salvage); } catch(e3) {
        variations = { error: 'parse failed', raw: geminiText.substring(0,2000) };
      }
    }
  }
}

const hooks = variations.new_hooks || [];
const lengths = variations.length_variants || [];
const angles = variations.angle_variants || [];

// Build Airtable records for each variation
const records = [];
const projectId = original.project_id;
const conceptId = original.concept_id;
const baseNum = original.script_number || '1';

// Hook variations — create as new scripts with swapped hooks
for (let i = 0; i < hooks.length; i++) {
  const h = hooks[i];
  records.push({
    fields: {
      hook: h.hook_text,
      hook_reinforcement: original.hook_reinforcement,
      problem: original.problem,
      solution: original.solution,
      proof: original.proof,
      cta: original.cta,
      full_script: `[${h.type.toUpperCase()} HOOK]\n${h.hook_text}\n\n${original.problem}\n\n${original.solution}\n\n${original.proof}\n\n${original.cta}`,
      visual_direction: original.visual_direction,
      creator_notes: `Repurposed: ${h.type} hook variant. ${h.why_it_works}`,
      estimated_duration: original.estimated_duration,
      concept_story: `[REPURPOSED - ${h.type} hook] ${original.concept_story}`,
      script_number: `${baseNum}-H${i+1}`,
      ...(projectId ? { project_id: [projectId] } : {}),
      ...(conceptId ? { concept_id: [conceptId] } : {})
    }
  });
}

// Length variations
for (const lv of lengths) {
  records.push({
    fields: {
      full_script: lv.full_script,
      visual_direction: lv.visual_notes || '',
      creator_notes: `Repurposed: ${lv.duration} version. Energy: ${lv.energy}`,
      estimated_duration: lv.duration,
      concept_story: `[REPURPOSED - ${lv.duration}] ${original.concept_story}`,
      script_number: `${baseNum}-${lv.duration.replace('s','')}S`,
      ...(projectId ? { project_id: [projectId] } : {}),
      ...(conceptId ? { concept_id: [conceptId] } : {})
    }
  });
}

// Angle variations
for (const av of angles) {
  records.push({
    fields: {
      hook: av.hook || '',
      cta: av.cta || '',
      full_script: av.full_script,
      visual_direction: av.visual_notes || '',
      creator_notes: `Repurposed: ${av.angle} angle. Energy: ${av.energy}`,
      estimated_duration: av.duration || '30s',
      concept_story: `[REPURPOSED - ${av.angle}] ${original.concept_story}`,
      script_number: `${baseNum}-${av.angle.substring(0,3).toUpperCase()}`,
      ...(projectId ? { project_id: [projectId] } : {}),
      ...(conceptId ? { concept_id: [conceptId] } : {})
    }
  });
}

// Build Slack message
const slackLines = [
  `*Content Repurposed: Script ${baseNum}*`,
  `Original: ${(original.hook || '').substring(0, 80)}...`,
  '',
  `*New Hooks (${hooks.length}):*`
];
for (const h of hooks) {
  slackLines.push(`> *${h.type}*: ${h.hook_text}`);
}
slackLines.push('');
slackLines.push(`*Length Variants (${lengths.length}):*`);
for (const lv of lengths) {
  slackLines.push(`> *${lv.duration}*: ${(lv.full_script || '').substring(0, 100)}...`);
}
slackLines.push('');
slackLines.push(`*Angle Variants (${angles.length}):*`);
for (const av of angles) {
  slackLines.push(`> *${av.angle}*: ${(av.full_script || '').substring(0, 100)}...`);
}
slackLines.push('');
slackLines.push(`_Total: ${records.length} new script variations created_`);

// Check if this went through self-eval retry
try {
  const evalData = $('rep-parse-eval').first().json;
  if (evalData.weakCount > 0) {
    slackLines.push(`_Self-eval: ${evalData.weakCount} weak variation(s) were auto-improved before publishing_`);
  } else {
    slackLines.push(`_Self-eval: All variations passed quality threshold on first pass_`);
  }
} catch(e) {
  // eval node may not have run in this path
}

// Batch records (max 10 per Airtable request)
const batches = [];
for (let i = 0; i < records.length; i += 10) {
  batches.push(records.slice(i, i + 10));
}

return [{ json: {
  script_id: original.script_id,
  variations_json: JSON.stringify(variations),
  records: records,
  batches: batches,
  batch_count: batches.length,
  total_variations: records.length,
  slack_message: slackLines.join('\n'),
  hooks_summary: hooks.map(h => `${h.type}: ${h.hook_text}`).join(' | '),
  original_hook: original.hook
}}];
